// Ported from the Node app's Sequelize model Homework (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class HomeworkConfiguration : IEntityTypeConfiguration<Homework>
{
    public void Configure(EntityTypeBuilder<Homework> builder)
    {
        builder.ToTable("homework");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.ClassId).HasColumnName("class_id");
        builder.Property(e => e.SubjectId).HasColumnName("subject_id");
        builder.Property(e => e.Title).HasColumnName("title").HasColumnType("nvarchar(160)").HasMaxLength(160).IsRequired();
        builder.Property(e => e.Description).HasColumnName("description").HasColumnType("nvarchar(max)");
        builder.Property(e => e.AssignedOn).HasColumnName("assigned_on").HasColumnType("date");
        builder.Property(e => e.DueDate).HasColumnName("due_date").HasColumnType("date");
        builder.Property(e => e.MaxMarks).HasColumnName("max_marks");
        builder.Property(e => e.CreatedBy).HasColumnName("created_by");
        builder.Property(e => e.CreatedByName).HasColumnName("created_by_name").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.HasOne(e => e.SchoolClass).WithMany(p => p.Homework).HasForeignKey(e => e.ClassId).OnDelete(DeleteBehavior.NoAction);
        builder.HasOne(e => e.Subject).WithMany(p => p.Homework).HasForeignKey(e => e.SubjectId).OnDelete(DeleteBehavior.NoAction);
    }
}
